"""Distributed skill directories must not ship generated bytecode.

Run with: python -m unittest tests/test_distribution_hygiene.py -v
"""
import shutil
import subprocess
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def is_bytecode(path: str) -> bool:
    parts = path.split("/")
    return "__pycache__" in parts or parts[-1].endswith((".pyc", ".pyo", ".pyd"))


class DistributionHygieneTests(unittest.TestCase):
    def test_bytecode_detection(self):
        self.assertTrue(is_bytecode("skills/a/scripts/__pycache__/x.cpython-312.pyc"))
        self.assertTrue(is_bytecode("skills/a/scripts/x.pyc"))
        self.assertFalse(is_bytecode("skills/a/scripts/convert.py"))

    def test_no_tracked_bytecode_in_skills(self):
        git = shutil.which("git")
        if git is None or not (ROOT / ".git").exists():
            self.skipTest("git checkout required")
        tracked = subprocess.run(
            [git, "ls-files", "-z", "--", "skills"], cwd=ROOT,
            capture_output=True, check=True,
        ).stdout.decode("utf-8").split("\0")
        self.assertEqual([path for path in tracked if path and is_bytecode(path)], [])

    def test_gitignore_excludes_bytecode(self):
        patterns = (ROOT / ".gitignore").read_text(encoding="utf-8").splitlines()
        self.assertIn("__pycache__/", patterns)
        self.assertIn("*.py[cod]", patterns)


if __name__ == "__main__":
    unittest.main()
